import { z } from "zod";
import { ApiError, now } from "./service";
import { resolvePricingDecision } from "./pricing.server";

export type OpsDB = {
  prepare(sql: string): { bind(...values: unknown[]): any; first<T = any>(): Promise<T | null>; all<T = any>(): Promise<{ results: T[] }>; run(): Promise<any> };
  batch(statements: any[]): Promise<unknown>;
};

const id=(p:string)=>`${p}_${crypto.randomUUID()}`;
const hex=(b:Uint8Array)=>[...b].map(x=>x.toString(16).padStart(2,"0")).join("");
async function sha256(s:string){return hex(new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s))));}
const ms=(iso:string|null|undefined)=>iso?Date.parse(String(iso)):NaN;
const ageSeconds=(iso:string|null|undefined)=>Number.isFinite(ms(iso))?Math.max(0,Math.floor((Date.now()-ms(iso))/1000)):null;
const redactDiagnostic=(value:string)=>String(value||"")
  .replace(/(authorization\s*[:=]\s*(?:bearer\s+)?)[^\s,;]+/ig,"$1[REDACTED]")
  .replace(/fore_svc_[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g,"fore_svc_[REDACTED]")
  .replace(/\b(?:sk|rk)_(?:live|test)_[A-Za-z0-9_-]+\b/g,"[REDACTED_STRIPE_SECRET]")
  .replace(/([?&](?:token|secret|key|signature|password)=)[^&#\s]+/ig,"$1[REDACTED]");
function safeOutboundHttpsUrl(raw:string,label:string){const u=new URL(raw);if(u.protocol!=="https:")throw new ApiError(503,`${label} must use HTTPS.`);if(u.username||u.password)throw new ApiError(503,`${label} cannot contain embedded credentials.`);const h=u.hostname.toLowerCase().replace(/^\[|\]$/g,"");if(h==="localhost"||h.endsWith(".localhost")||h.endsWith(".local")||h.endsWith(".internal")||h==="::1"||h.startsWith("fe80:")||h.startsWith("fc")||h.startsWith("fd"))throw new ApiError(503,`${label} cannot target a local/private host.`);const m=h.match(/^(\d+)\.(\d+)\.(\d+)\.(\d+)$/);if(m){const [a,b]=[Number(m[1]),Number(m[2])];if(a===10||a===127||a===0||(a===169&&b===254)||(a===172&&b>=16&&b<=31)||(a===192&&b===168))throw new ApiError(503,`${label} cannot target a private address.`);}return u;}

export type RequestTrace = { requestId:string; traceId:string; spanId:string; parentSpanId:string|null; startedAt:string; startedMs:number; traceparent:string };
function randomHex(bytes:number){return hex(crypto.getRandomValues(new Uint8Array(bytes)));}
export function beginRequestTrace(request:Request):RequestTrace{
  const incoming=request.headers.get("traceparent")||"",m=incoming.match(/^00-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$/i),traceId=m?m[1].toLowerCase():randomHex(16),parentSpanId=m?m[2].toLowerCase():null,spanId=randomHex(8),incomingRequestId=request.headers.get("x-request-id")||"",requestId=/^[A-Za-z0-9._:-]{8,160}$/.test(incomingRequestId)?incomingRequestId:`req_${crypto.randomUUID()}`,startedAt=now();
  return{requestId,traceId,spanId,parentSpanId,startedAt,startedMs:Date.now(),traceparent:`00-${traceId}-${spanId}-01`};
}

export async function recordHttpRequest(db:OpsDB,trace:RequestTrace,request:Request,response:Response,input:{actorKind?:string;storefrontCountry?:string|null;errorClass?:string|null}={}){
  const endedAt=now(),duration=Math.max(0,Date.now()-trace.startedMs),route=new URL(request.url).pathname.replace(/\b[0-9a-f]{8}-[0-9a-f-]{27,}\b/ig,":id");
  try{await db.batch([
    db.prepare("INSERT OR IGNORE INTO ops_http_requests(id,request_id,trace_id,span_id,parent_span_id,method,route,status_code,duration_ms,actor_kind,storefront_country,error_class,sampled,occurred_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,1,?)").bind(id("httpreq"),trace.requestId,trace.traceId,trace.spanId,trace.parentSpanId,request.method,route,response.status,duration,input.actorKind||"anonymous",input.storefrontCountry||null,input.errorClass||null,trace.startedAt),
    db.prepare("INSERT INTO ops_trace_spans(id,trace_id,span_id,parent_span_id,span_name,span_kind,status,started_at,ended_at,duration_ms,attributes_json) VALUES(?,?,?,?,?,'server',?,?,?,?,?)").bind(id("span"),trace.traceId,trace.spanId,trace.parentSpanId,`${request.method} ${route}`,response.status>=500?"error":"ok",trace.startedAt,endedAt,duration,JSON.stringify({statusCode:response.status,requestId:trace.requestId,actorKind:input.actorKind||"anonymous",storefrontCountry:input.storefrontCountry||null})),
    db.prepare("INSERT INTO ops_metric_points(id,metric_name,metric_type,value,unit,labels_json,observed_at) VALUES(?, 'http.server.duration','histogram',?,'ms',?,?)").bind(id("metric"),duration,JSON.stringify({method:request.method,route,statusClass:`${Math.floor(response.status/100)}xx`}),endedAt),
  ]);}catch{}
  console.log(JSON.stringify({level:response.status>=500?"error":"info",event:"http_request",requestId:trace.requestId,traceId:trace.traceId,spanId:trace.spanId,method:request.method,route,status:response.status,durationMs:duration,storefrontCountry:input.storefrontCountry||null,at:endedAt}));
}

export async function recordErrorEvent(db:OpsDB,trace:RequestTrace|undefined,request:Request,error:unknown,context:unknown={}){
  const e=error instanceof Error?error:new Error(String(error)),route=new URL(request.url).pathname,safeMessage=redactDiagnostic(String(e.message||"Unknown error")).slice(0,1200),safeStack=redactDiagnostic(String(e.stack||"")).slice(0,4000),signature=`${e.name}|${safeMessage}|${route}`,fingerprint=(await sha256(signature)).slice(0,32);
  try{await db.prepare("INSERT INTO ops_error_events(id,request_id,trace_id,fingerprint,error_class,message,stack_excerpt,route,severity,context_json,occurred_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)").bind(id("opserr"),trace?.requestId||request.headers.get("x-fore-request-id")||null,trace?.traceId||request.headers.get("x-fore-trace-id")||null,fingerprint,e.name||"Error",safeMessage,safeStack,route,"error",JSON.stringify(context||{}),now()).run();}catch{}
  console.error(JSON.stringify({level:"error",event:"application_error",requestId:trace?.requestId||request.headers.get("x-fore-request-id")||null,traceId:trace?.traceId||request.headers.get("x-fore-trace-id")||null,fingerprint,errorClass:e.name,message:safeMessage,route,at:now()}));
}

function percentile(values:number[],p:number){if(!values.length)return 0;const sorted=[...values].sort((a,b)=>a-b),idx=Math.min(sorted.length-1,Math.max(0,Math.ceil(p*sorted.length)-1));return sorted[idx];}
async function latest(db:OpsDB,sql:string,...args:any[]){return db.prepare(sql).bind(...args).first<any>();}

async function dependencySnapshot(db:OpsDB){
  const [catalog,webhook,feed,notifications,recs,publishing,deadLetters,backup,restore]=await Promise.all([
    latest(db,"SELECT completed_at,status,error FROM gutenberg_ingest_runs ORDER BY started_at DESC LIMIT 1"),
    latest(db,"SELECT received_at,processed_at,status,error,event_type FROM commerce_webhook_events ORDER BY received_at DESC LIMIT 1"),
    latest(db,"SELECT received_at,validated_at,applied_at,status,error_summary FROM publisher_feed_submissions WHERE environment='production' ORDER BY received_at DESC LIMIT 1"),
    latest(db,"SELECT MIN(COALESCE(available_at,created_at)) oldest,COUNT(*) count FROM notification_delivery_jobs WHERE status IN ('pending','retry','processing')"),
    latest(db,"SELECT MIN(available_at) oldest,COUNT(*) count FROM recommendation_jobs WHERE status IN ('pending','retry','processing','leased')"),
    latest(db,"SELECT MIN(available_at) oldest,COUNT(*) count FROM publishing_validation_jobs WHERE status IN ('pending','leased')"),
    latest(db,"SELECT COUNT(*) count,MIN(dead_lettered_at) oldest FROM ops_dead_letters WHERE replayed_at IS NULL"),
    latest(db,"SELECT * FROM ops_backup_artifacts WHERE status='verified' ORDER BY snapshot_at DESC LIMIT 1"),
    latest(db,"SELECT * FROM ops_restore_drills WHERE status IN ('passed','failed') ORDER BY started_at DESC LIMIT 1"),
  ]);
  return{catalog,webhook,feed,notifications,recs,publishing,deadLetters,backup,restore};
}

async function storeCheck(db:OpsDB,checkKey:string,type:string,status:"healthy"|"degraded"|"down"|"unknown",input:{latencyMs?:number|null;freshnessSeconds?:number|null;details?:unknown}){const at=now();await db.prepare("INSERT INTO ops_dependency_checks(id,check_key,dependency_type,status,latency_ms,freshness_seconds,details_json,checked_at) VALUES(?,?,?,?,?,?,?,?)").bind(id("dep"),checkKey,type,status,input.latencyMs??null,input.freshnessSeconds??null,JSON.stringify(input.details||{}),at).run();return{checkKey,type,status,latencyMs:input.latencyMs??null,freshnessSeconds:input.freshnessSeconds??null,details:input.details||{},checkedAt:at};}

async function upsertIncident(db:OpsDB,ruleKey:string,severity:"warning"|"critical",dedupeKey:string,title:string,summary:string,metadata:unknown,active:boolean){
  const rule=await db.prepare("SELECT id,notification_target FROM ops_alert_rules WHERE rule_key=? AND active=1").bind(ruleKey).first<any>();if(!rule)return;
  const existing=await db.prepare("SELECT id,status FROM ops_incidents WHERE dedupe_key=? AND status IN ('open','acknowledged')").bind(dedupeKey).first<any>();
  const at=now();
  if(active){
    if(existing){await db.prepare("UPDATE ops_incidents SET severity=?,title=?,summary=?,metadata_json=? WHERE id=?").bind(severity,title,summary,JSON.stringify(metadata||{}),existing.id).run();}
    else {const incidentId=id("incident");await db.batch([
      db.prepare("INSERT INTO ops_incidents(id,alert_rule_id,dedupe_key,severity,status,title,summary,opened_at,metadata_json) VALUES(?,?,?,?, 'open',?,?,?,?)").bind(incidentId,rule.id,dedupeKey,severity,title,summary,at,JSON.stringify(metadata||{})),
      db.prepare("INSERT INTO ops_alert_deliveries(id,incident_id,event_type,notification_target,status,attempts,max_attempts,available_at,created_at,updated_at) VALUES(?,?, 'opened',?,'pending',0,8,?,?,?)").bind(id("alertdel"),incidentId,String(rule.notification_target||"oncall"),at,at,at),
    ]);}
  } else if(existing){await db.batch([
    db.prepare("UPDATE ops_incidents SET status='resolved',resolved_at=?,resolved_by_user_id='system' WHERE id=?").bind(at,existing.id),
    db.prepare("INSERT OR IGNORE INTO ops_alert_deliveries(id,incident_id,event_type,notification_target,status,attempts,max_attempts,available_at,created_at,updated_at) VALUES(?,?, 'resolved',?,'pending',0,8,?,?,?)").bind(id("alertdel"),existing.id,String(rule.notification_target||"oncall"),at,at,at),
  ]);}
}

export async function runOperationalChecks(db:OpsDB){
  const t0=Date.now();await db.prepare("SELECT 1 ok").first<any>();const dbLatency=Date.now()-t0,deps=await dependencySnapshot(db),checks:any[]=[];
  checks.push(await storeCheck(db,"database","database",dbLatency<250?"healthy":dbLatency<1000?"degraded":"down",{latencyMs:dbLatency,details:{probe:"SELECT 1"}}));
  const catalogAge=ageSeconds(deps.catalog?.completed_at||deps.catalog?.started_at),catalogStatus=!deps.catalog?"unknown":deps.catalog.status==="failed"?"down":catalogAge!=null&&catalogAge>21600?"degraded":"healthy";
  checks.push(await storeCheck(db,"catalog-freshness","catalog",catalogStatus as any,{freshnessSeconds:catalogAge,details:deps.catalog||{}}));
  const webhookAge=ageSeconds(deps.webhook?.received_at),webhookBad=deps.webhook?.status==="failed"||deps.webhook?.error,webhookStatus=!deps.webhook?"unknown":webhookBad?"down":webhookAge!=null&&webhookAge>86400?"degraded":"healthy";
  checks.push(await storeCheck(db,"payment-webhooks","stripe",webhookStatus as any,{freshnessSeconds:webhookAge,details:deps.webhook||{}}));
  const feedAge=ageSeconds(deps.feed?.received_at),feedBad=deps.feed?.status==="failed",feedStatus=!deps.feed?"unknown":feedBad?"degraded":feedAge!=null&&["received","validating","applying"].includes(String(deps.feed.status))&&feedAge>3600?"degraded":"healthy";
  checks.push(await storeCheck(db,"publisher-feeds","publisher_feed",feedStatus as any,{freshnessSeconds:feedAge,details:deps.feed||{}}));
  const dlqCount=Number(deps.deadLetters?.count||0);checks.push(await storeCheck(db,"dead-letters","other",dlqCount?"degraded":"healthy",{freshnessSeconds:ageSeconds(deps.deadLetters?.oldest),details:{count:dlqCount}}));
  const backupAge=ageSeconds(deps.backup?.snapshot_at),rpo=await db.prepare("SELECT rpo_minutes,restore_drill_frequency_days FROM ops_recovery_objectives WHERE service_key='primary-database'").first<any>(),backupLimit=Number(rpo?.rpo_minutes||15)*60;
  checks.push(await storeCheck(db,"database-backup","database",deps.backup?(backupAge!=null&&backupAge>backupLimit?"down":"healthy"):"unknown",{freshnessSeconds:backupAge,details:deps.backup||{}}));
  const restoreAge=ageSeconds(deps.restore?.started_at),restoreLimit=Number(rpo?.restore_drill_frequency_days||30)*86400,restoreHealthy=deps.restore&&deps.restore.status==="passed"&&restoreAge!=null&&restoreAge<=restoreLimit;
  checks.push(await storeCheck(db,"restore-drill","database",restoreHealthy?"healthy":deps.restore?"down":"unknown",{freshnessSeconds:restoreAge,details:deps.restore||{}}));
  await upsertIncident(db,"catalog-stale","warning","catalog:stale","Catalog freshness exceeded","No successful catalog refresh is inside the freshness objective.",{ageSeconds:catalogAge},catalogStatus!=="healthy"&&catalogStatus!=="unknown");
  await upsertIncident(db,"payment-webhook-failure","critical","stripe:webhook","Payment webhook processing unhealthy","Latest Stripe webhook is failed or stale.",{latest:deps.webhook},webhookStatus==="down");
  await upsertIncident(db,"publisher-feed-backlog","warning","publisher-feed:backlog","Publisher feed backlog too old","A production publisher feed is failing or has exceeded its processing window.",{latest:deps.feed},feedStatus==="degraded");
  await upsertIncident(db,"dead-letter-present","warning","queues:dead-letter","Dead-letter queue contains jobs",`${dlqCount} unreplayed dead-letter job(s) require attention.`,{count:dlqCount},dlqCount>0);
  await upsertIncident(db,"backup-stale","critical","backup:primary-database","Verified backup is stale or missing","No verified primary database backup satisfies the configured RPO.",{ageSeconds:backupAge,rpoSeconds:backupLimit,backupPresent:!!deps.backup},!deps.backup||backupAge==null||backupAge>backupLimit);
  await upsertIncident(db,"restore-drill-overdue","critical","restore:primary-database","Restore verification is overdue or missing","No recent passing primary database restore drill satisfies the configured policy.",{ageSeconds:restoreAge,limitSeconds:restoreLimit,drillPresent:!!deps.restore},!deps.restore||!restoreHealthy);
  const queues=(await db.prepare(`SELECT q.queue_key,q.warn_oldest_seconds,q.critical_oldest_seconds,COUNT(j.id) queued,MIN(j.created_at) oldest FROM ops_queue_definitions q LEFT JOIN ops_jobs j ON j.queue_key=q.queue_key AND j.status IN ('pending','retry','leased') GROUP BY q.queue_key`).all<any>()).results;
  for(const q of queues){const queueAge=ageSeconds(q.oldest),queued=Number(q.queued||0),warn=Number(q.warn_oldest_seconds||300),critical=Number(q.critical_oldest_seconds||1800),queueStatus=!queued?"healthy":queueAge!=null&&queueAge>=critical?"down":queueAge!=null&&queueAge>=warn?"degraded":"healthy";checks.push(await storeCheck(db,`queue:${q.queue_key}`,"other",queueStatus as any,{freshnessSeconds:queueAge,details:{queued,warnSeconds:warn,criticalSeconds:critical}}));await upsertIncident(db,"queue-backlog",queueStatus==="down"?"critical":"warning",`queue:backlog:${q.queue_key}`,`Queue backlog: ${q.queue_key}`,`${queued} job(s) are older than this queue's service threshold.`,{queued,ageSeconds:queueAge,warnSeconds:warn,criticalSeconds:critical},queueStatus!=="healthy");}
  return{checkedAt:now(),checks};
}

export async function probeObjectStorage(db:OpsDB,bucket:any){
  let result:any;
  if(!bucket?.put||!bucket?.head||!bucket?.get||!bucket?.delete)result=await storeCheck(db,"object-storage","storage","unknown",{details:{reason:"bucket binding unavailable"}});
  else {const key=`ops/health/${crypto.randomUUID()}.txt`,payload=new TextEncoder().encode("fore-storage-probe"),start=Date.now();
    try{
      await bucket.put(key,payload,{httpMetadata:{contentType:"text/plain",cacheControl:"no-store"}});
      const head=await bucket.head(key),object=await bucket.get(key),body=object?await new Response(object.body).text():"";await bucket.delete(key);
      const ok=!!head&&body==="fore-storage-probe",latency=Date.now()-start;
      result=await storeCheck(db,"object-storage","storage",ok?(latency<1500?"healthy":"degraded"):"down",{latencyMs:latency,details:{writeReadDelete:true,size:Number(head?.size||0),verified:ok}});
    }catch(e){try{await bucket.delete(key);}catch{};result=await storeCheck(db,"object-storage","storage","down",{latencyMs:Date.now()-start,details:{error:e instanceof Error?e.message:String(e)}});}
  }
  await upsertIncident(db,"object-storage-down","critical","storage:r2","Object storage probe failing","R2 write/read/delete verification is not healthy.",{check:result},result.status==="down");
  return result;
}

export async function probeCdnEdge(db:OpsDB,publicUrl:string){
  if(!publicUrl)return storeCheck(db,"cdn-edge","cdn","unknown",{details:{reason:"FORE_PUBLIC_URL unavailable"}});
  let endpoint:string;try{const u=new URL(publicUrl);if(u.protocol!=="https:"&&u.hostname!=="localhost"&&u.hostname!=="127.0.0.1")throw new Error("HTTPS required");u.pathname="/api/fore/health/live";u.search=`?probe=${crypto.randomUUID()}`;endpoint=u.toString();}catch(e){return storeCheck(db,"cdn-edge","cdn","unknown",{details:{reason:e instanceof Error?e.message:String(e)}});}
  const start=Date.now(),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);let result:any;try{const r=await fetch(endpoint,{headers:{"cache-control":"no-cache"},signal:controller.signal,redirect:"error"});const body=await r.json().catch(()=>null) as any,latency=Date.now()-start,ok=r.ok&&body?.ok===true;result=await storeCheck(db,"cdn-edge","cdn",ok?(latency<1200?"healthy":"degraded"):"down",{latencyMs:latency,details:{status:r.status,edgeHealth:ok}});}catch(e){result=await storeCheck(db,"cdn-edge","cdn","down",{latencyMs:Date.now()-start,details:{error:e instanceof Error?e.message:String(e)}});}finally{clearTimeout(timer);}
  await upsertIncident(db,"cdn-edge-down","critical","cdn:edge","CDN edge probe failing","Public Cove health endpoint is unreachable or unhealthy through the CDN.",{check:result},result.status==="down");return result;
}

export async function refreshSloMeasurements(db:OpsDB){
  const slos=(await db.prepare("SELECT * FROM ops_slo_definitions WHERE status='active'").all<any>()).results,out:any[]=[];
  for(const s of slos){const end=now(),start=new Date(Date.now()-Number(s.window_days||30)*86400000).toISOString();let good=0,total=0,details:any={};
    if(s.indicator_type==="availability"){const r=await db.prepare("SELECT COUNT(*) total,SUM(CASE WHEN status_code<500 THEN 1 ELSE 0 END) good FROM ops_http_requests WHERE occurred_at>=? AND route LIKE '/api/fore/%'").bind(start).first<any>();total=Number(r?.total||0);good=Number(r?.good||0);}
    else if(s.indicator_type==="latency"){const r=await db.prepare("SELECT COUNT(*) total,SUM(CASE WHEN duration_ms<=? AND status_code<500 THEN 1 ELSE 0 END) good FROM ops_http_requests WHERE occurred_at>=? AND route LIKE '/api/fore/%'").bind(Number(s.threshold_ms||750),start).first<any>();total=Number(r?.total||0);good=Number(r?.good||0);}
    else if(s.indicator_type==="synthetic_success"){const r=await db.prepare("SELECT COUNT(*) total,SUM(CASE WHEN sr.status='passed' THEN 1 ELSE 0 END) good FROM ops_synthetic_runs sr JOIN ops_synthetic_checks sc ON sc.id=sr.check_id WHERE sr.started_at>=? AND sc.check_type='checkout'").bind(start).first<any>();total=Number(r?.total||0);good=Number(r?.good||0);}
    else if(s.indicator_type==="freshness"){const c=await db.prepare("SELECT * FROM ops_dependency_checks WHERE check_key='catalog-freshness' AND checked_at>=? ORDER BY checked_at").bind(start).all<any>();total=c.results.length;good=c.results.filter((r:any)=>r.status==="healthy").length;}
    else if(s.indicator_type==="webhook_success"){const r=await db.prepare("SELECT COUNT(*) total,SUM(CASE WHEN status='processed' OR status='succeeded' THEN 1 ELSE 0 END) good FROM commerce_webhook_events WHERE received_at>=?").bind(start).first<any>();total=Number(r?.total||0);good=Number(r?.good||0);}
    const achieved=total?Math.floor(good*10000/total):10000,target=Number(s.target_bps),budget=Math.max(0,10000-Math.max(0,10000-achieved)*10000/Math.max(1,10000-target));const mid=id("slom");await db.prepare("INSERT INTO ops_slo_measurements(id,slo_id,window_start,window_end,good_events,total_events,achieved_bps,error_budget_remaining_bps,details_json,measured_at) VALUES(?,?,?,?,?,?,?,?,?,?)").bind(mid,s.id,start,end,good,total,achieved,Math.floor(budget),JSON.stringify(details),end).run();out.push({sloKey:s.slo_key,good,total,achievedBps:achieved,targetBps:target,errorBudgetRemainingBps:Math.floor(budget)});
  }
  return{measuredAt:now(),slos:out};
}

export async function runSyntheticChecks(db:OpsDB){const checks=(await db.prepare("SELECT * FROM ops_synthetic_checks WHERE active=1 ORDER BY check_key").all<any>()).results,results:any[]=[];for(const check of checks){const start=Date.now(),steps:any[]=[];let status:"passed"|"failed"|"degraded"="passed",error="";try{if(check.check_type==="storefront"){const r=await db.prepare("SELECT COUNT(*) count FROM retail_product_availability rpa JOIN products p ON p.id=rpa.product_id WHERE rpa.territory_code=? AND p.storefront_status='active'").bind(check.storefront_country||"US").first<any>();const count=Number(r?.count||0);steps.push({step:"available-products",ok:count>0,count});if(!count)status="degraded";}else if(check.check_type==="search"){const r=await db.prepare("SELECT COUNT(*) count FROM catalog_search_documents").first<any>();const count=Number(r?.count||0);steps.push({step:"search-documents",ok:count>0,count});if(!count)status="degraded";}else if(check.check_type==="checkout"){const product=await db.prepare(`SELECT p.id FROM products p JOIN offers o ON o.product_id=p.id AND o.active=1 JOIN retail_product_availability rpa ON rpa.product_id=p.id AND rpa.territory_code=? WHERE p.storefront_status='active' ORDER BY p.updated_at DESC LIMIT 1`).bind(check.storefront_country||"US").first<any>();if(!product)throw new Error("No purchasable synthetic checkout product is available.");const decision=await resolvePricingDecision(db as any,String(product.id),String(check.storefront_country||"US"),{persist:false});if(!decision)throw new Error("Pricing/rights resolution denied the synthetic checkout product.");steps.push({step:"rights-and-price",ok:true,productId:product.id,currency:decision.currency,amountMinor:decision.amountMinor});}else steps.push({step:"configured",ok:true});}catch(e){status="failed";error=e instanceof Error?e.message:String(e);steps.push({step:"exception",ok:false,error});}const finished=now(),duration=Date.now()-start,runId=id("synrun");await db.prepare("INSERT INTO ops_synthetic_runs(id,check_id,status,duration_ms,step_results_json,error,started_at,finished_at) VALUES(?,?,?,?,?,?,?,?)").bind(runId,check.id,status,duration,JSON.stringify(steps),error,new Date(start).toISOString(),finished).run();if(check.check_type==="checkout")await upsertIncident(db,"synthetic-checkout-failing","critical",`synthetic:${check.check_key}`,"Synthetic checkout failing",error||"Checkout synthetic is not passing.",{checkKey:check.check_key,steps},status==="failed");results.push({checkKey:check.check_key,status,durationMs:duration,steps,error});}return{runAt:now(),results};}

export async function operationsSnapshot(db:OpsDB){const since=new Date(Date.now()-3600000).toISOString(),[requests,errors,incidents,checks,slos,workers,deadLetters,backups,restores,deployments,synthetics,capacity,queues,alertDeliveries]=await Promise.all([db.prepare("SELECT status_code,duration_ms,route,occurred_at FROM ops_http_requests WHERE occurred_at>=? ORDER BY occurred_at DESC LIMIT 5000").bind(since).all<any>(),db.prepare("SELECT * FROM ops_error_events ORDER BY occurred_at DESC LIMIT 200").all<any>(),db.prepare("SELECT * FROM ops_incidents ORDER BY CASE status WHEN 'open' THEN 0 WHEN 'acknowledged' THEN 1 ELSE 2 END,opened_at DESC LIMIT 200").all<any>(),db.prepare("SELECT d.* FROM ops_dependency_checks d JOIN (SELECT check_key,MAX(checked_at) mx FROM ops_dependency_checks GROUP BY check_key) x ON x.check_key=d.check_key AND x.mx=d.checked_at ORDER BY d.check_key").all<any>(),db.prepare("SELECT s.slo_key,s.description,s.target_bps,s.indicator_type,m.* FROM ops_slo_definitions s LEFT JOIN ops_slo_measurements m ON m.id=(SELECT id FROM ops_slo_measurements WHERE slo_id=s.id ORDER BY measured_at DESC LIMIT 1) WHERE s.status='active' ORDER BY s.slo_key").all<any>(),db.prepare("SELECT * FROM ops_worker_runs ORDER BY started_at DESC LIMIT 200").all<any>(),db.prepare("SELECT * FROM ops_dead_letters WHERE replayed_at IS NULL ORDER BY dead_lettered_at DESC LIMIT 200").all<any>(),db.prepare("SELECT * FROM ops_backup_artifacts ORDER BY snapshot_at DESC LIMIT 100").all<any>(),db.prepare("SELECT * FROM ops_restore_drills ORDER BY started_at DESC LIMIT 100").all<any>(),db.prepare("SELECT * FROM ops_deployments ORDER BY created_at DESC LIMIT 100").all<any>(),db.prepare("SELECT sc.check_key,sc.name,sc.check_type,sr.* FROM ops_synthetic_checks sc LEFT JOIN ops_synthetic_runs sr ON sr.id=(SELECT id FROM ops_synthetic_runs WHERE check_id=sc.id ORDER BY started_at DESC LIMIT 1) ORDER BY sc.check_key").all<any>(),db.prepare("SELECT * FROM ops_capacity_tests ORDER BY created_at DESC LIMIT 100").all<any>(),db.prepare(`SELECT q.*,SUM(CASE WHEN j.status IN ('pending','retry') THEN 1 ELSE 0 END) queued_count,MIN(CASE WHEN j.status IN ('pending','retry') THEN j.available_at END) oldest_available_at,SUM(CASE WHEN j.status='leased' THEN 1 ELSE 0 END) leased_count,SUM(CASE WHEN j.status='dead_letter' THEN 1 ELSE 0 END) dead_count FROM ops_queue_definitions q LEFT JOIN ops_jobs j ON j.queue_key=q.queue_key GROUP BY q.queue_key ORDER BY q.queue_key`).all<any>(),db.prepare("SELECT * FROM ops_alert_deliveries ORDER BY created_at DESC LIMIT 200").all<any>()]);const durations=requests.results.map((r:any)=>Number(r.duration_ms||0)),total=requests.results.length,serverErrors=requests.results.filter((r:any)=>Number(r.status_code)>=500).length;return{generatedAt:now(),http:{windowMinutes:60,total,serverErrors,errorRateBps:total?Math.floor(serverErrors*10000/total):0,p50Ms:percentile(durations,.5),p95Ms:percentile(durations,.95),p99Ms:percentile(durations,.99)},errors:errors.results,incidents:incidents.results,dependencyChecks:checks.results,slos:slos.results,workers:workers.results,deadLetters:deadLetters.results,backups:backups.results,restoreDrills:restores.results,deployments:deployments.results,synthetics:synthetics.results,capacityTests:capacity.results,queues:queues.results,alertDeliveries:alertDeliveries.results};}

export async function acknowledgeIncident(db:OpsDB,userId:string,raw:unknown){const x=z.object({incidentId:z.string().min(1),status:z.enum(["acknowledged","resolved"])}).parse(raw),at=now();const before=await db.prepare("SELECT i.id,i.status,r.notification_target FROM ops_incidents i LEFT JOIN ops_alert_rules r ON r.id=i.alert_rule_id WHERE i.id=?").bind(x.incidentId).first<any>();if(!before)throw new ApiError(404,"Incident not found.");const row=await db.prepare(`UPDATE ops_incidents SET status=?,acknowledged_at=CASE WHEN ?='acknowledged' THEN COALESCE(acknowledged_at,?) ELSE acknowledged_at END,acknowledged_by_user_id=CASE WHEN ?='acknowledged' THEN COALESCE(acknowledged_by_user_id,?) ELSE acknowledged_by_user_id END,resolved_at=CASE WHEN ?='resolved' THEN ? ELSE resolved_at END,resolved_by_user_id=CASE WHEN ?='resolved' THEN ? ELSE resolved_by_user_id END WHERE id=? RETURNING id,status`).bind(x.status,x.status,at,x.status,userId,x.status,at,x.status,userId,x.incidentId).first<any>();if(x.status==="resolved"&&before.status!=="resolved")await db.prepare("INSERT OR IGNORE INTO ops_alert_deliveries(id,incident_id,event_type,notification_target,status,attempts,max_attempts,available_at,created_at,updated_at) VALUES(?,?, 'resolved',?,'pending',0,8,?,?,?)").bind(id("alertdel"),x.incidentId,String(before.notification_target||"oncall"),at,at,at).run();return row;}

export async function registerBackupArtifact(db:OpsDB,raw:unknown){const x=z.object({serviceKey:z.string().min(1).max(120),provider:z.string().min(1).max(120),providerBackupId:z.string().min(1).max(240),snapshotAt:z.string().datetime(),sizeBytes:z.number().int().nonnegative().nullable().optional(),checksumSha256:z.string().regex(/^[a-f0-9]{64}$/i).nullable().optional(),status:z.enum(["created","verified","failed","expired"]),verification:z.record(z.any()).default({})}).parse(raw),backupId=id("backup");if(x.status==="verified"&&!Object.keys(x.verification).length)throw new ApiError(400,"A verified backup requires provider verification evidence.");await db.prepare(`INSERT INTO ops_backup_artifacts(id,service_key,provider,provider_backup_id,snapshot_at,size_bytes,checksum_sha256,status,verification_json,verified_at,recorded_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(provider,provider_backup_id) DO UPDATE SET snapshot_at=excluded.snapshot_at,size_bytes=excluded.size_bytes,checksum_sha256=excluded.checksum_sha256,status=excluded.status,verification_json=excluded.verification_json,verified_at=excluded.verified_at,recorded_at=excluded.recorded_at`).bind(backupId,x.serviceKey,x.provider,x.providerBackupId,x.snapshotAt,x.sizeBytes??null,x.checksumSha256||null,x.status,JSON.stringify(x.verification),x.status==="verified"?now():null,now()).run();return{id:backupId,saved:true};}

export async function recordRestoreDrill(db:OpsDB,userId:string,raw:unknown){const x=z.object({id:z.string().optional(),serviceKey:z.string().min(1),backupArtifactId:z.string().nullable().optional(),environment:z.string().max(80).default("isolated"),startedAt:z.string().datetime(),finishedAt:z.string().datetime().nullable().optional(),restoreDurationSeconds:z.number().int().nonnegative().nullable().optional(),dataLossWindowSeconds:z.number().int().nonnegative().nullable().optional(),integrityCheckStatus:z.enum(["pending","passed","failed"]),applicationProbeStatus:z.enum(["pending","passed","failed"]),status:z.enum(["running","passed","failed"]),evidence:z.record(z.any()).default({})}).parse(raw),drillId=x.id||id("restore");if(x.status==="passed"){if(x.integrityCheckStatus!=="passed"||x.applicationProbeStatus!=="passed")throw new ApiError(400,"A passing restore drill requires both integrity and application probes to pass.");if(x.restoreDurationSeconds==null||x.dataLossWindowSeconds==null)throw new ApiError(400,"A passing restore drill must record measured restore duration and data-loss window.");const objective=await db.prepare("SELECT rpo_minutes,rto_minutes FROM ops_recovery_objectives WHERE service_key=?").bind(x.serviceKey).first<any>();if(!objective)throw new ApiError(409,"The service has no registered RPO/RTO objective.");if(x.restoreDurationSeconds>Number(objective.rto_minutes)*60)throw new ApiError(409,"Restore drill exceeded the service RTO.");if(x.dataLossWindowSeconds>Number(objective.rpo_minutes)*60)throw new ApiError(409,"Restore drill exceeded the service RPO.");if(x.backupArtifactId){const backup=await db.prepare("SELECT service_key,status FROM ops_backup_artifacts WHERE id=?").bind(x.backupArtifactId).first<any>();if(!backup||String(backup.service_key)!==x.serviceKey||String(backup.status)!=="verified")throw new ApiError(409,"A passing restore drill must reference a verified backup for the same service.");}if(!Object.keys(x.evidence).length)throw new ApiError(400,"A passing restore drill requires restore evidence.");}await db.prepare(`INSERT INTO ops_restore_drills(id,service_key,backup_artifact_id,environment,started_at,finished_at,restore_duration_seconds,data_loss_window_seconds,integrity_check_status,application_probe_status,status,evidence_json,performed_by_user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET finished_at=excluded.finished_at,restore_duration_seconds=excluded.restore_duration_seconds,data_loss_window_seconds=excluded.data_loss_window_seconds,integrity_check_status=excluded.integrity_check_status,application_probe_status=excluded.application_probe_status,status=excluded.status,evidence_json=excluded.evidence_json,performed_by_user_id=excluded.performed_by_user_id`).bind(drillId,x.serviceKey,x.backupArtifactId||null,x.environment,x.startedAt,x.finishedAt||null,x.restoreDurationSeconds??null,x.dataLossWindowSeconds??null,x.integrityCheckStatus,x.applicationProbeStatus,x.status,JSON.stringify(x.evidence),userId).run();return{id:drillId,status:x.status};}

export async function saveMigrationControl(db:OpsDB,userId:string,raw:unknown){const x=z.object({migrationName:z.string().min(1).max(240),backwardCompatible:z.boolean(),rollbackStrategy:z.enum(["down_sql","forward_fix","restore_required","expand_contract"]),rollbackSql:z.string().max(50000).default(""),minimumPreviousAppVersion:z.string().max(160).default(""),notes:z.string().max(4000).default("")}).parse(raw);if(x.rollbackStrategy==="down_sql"&&!x.rollbackSql.trim())throw new ApiError(400,"down_sql migration controls require rollbackSql.");const at=now();await db.prepare(`INSERT INTO ops_migration_controls(migration_name,backward_compatible,rollback_strategy,rollback_sql,minimum_previous_app_version,notes,reviewed_by_user_id,reviewed_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(migration_name) DO UPDATE SET backward_compatible=excluded.backward_compatible,rollback_strategy=excluded.rollback_strategy,rollback_sql=excluded.rollback_sql,minimum_previous_app_version=excluded.minimum_previous_app_version,notes=excluded.notes,reviewed_by_user_id=excluded.reviewed_by_user_id,reviewed_at=excluded.reviewed_at`).bind(x.migrationName,x.backwardCompatible?1:0,x.rollbackStrategy,x.rollbackSql,x.minimumPreviousAppVersion,x.notes,userId,at).run();return{migrationName:x.migrationName,reviewedAt:at};}

async function assertProductionSecurityReleaseGate(db:OpsDB,releaseVersion:string,strategy:string,healthCriteria:Record<string,any>){
  const emergencyException=String(healthCriteria?.securityExceptionReference||"").trim();
  if(strategy==="emergency"&&emergencyException)return;
  const provenance=await db.prepare("SELECT verified,provenance_reference,signature_reference FROM security_build_provenance WHERE release_id=? ORDER BY created_at DESC LIMIT 1").bind(releaseVersion).first<any>();
  if(!provenance||!Number(provenance.verified)||!String(provenance.provenance_reference||"").trim())throw new ApiError(409,"Production promotion requires verified build provenance for this release.");
  const sbom=await db.prepare("SELECT id FROM security_sboms WHERE release_id=? ORDER BY generated_at DESC LIMIT 1").bind(releaseVersion).first<any>();if(!sbom)throw new ApiError(409,"Production promotion requires an SBOM for this release.");
  for(const scanType of ["dependency","secret","sast"]){
    const scan=await db.prepare("SELECT id,status FROM security_scans WHERE scan_type=? AND target_type='release' AND target_id=? ORDER BY created_at DESC LIMIT 1").bind(scanType,releaseVersion).first<any>();
    if(!scan||!["passed","warning"].includes(String(scan.status)))throw new ApiError(409,`Production promotion requires a passing ${scanType} scan for this release.`);
    const blocking=await db.prepare(`SELECT id,severity,status,accepted_until FROM security_findings WHERE scan_id=? AND severity IN ('critical','high') AND (status IN ('open','triaged') OR (status='accepted' AND (accepted_until IS NULL OR accepted_until<=?))) LIMIT 1`).bind(scan.id,now()).first<any>();
    if(blocking)throw new ApiError(409,`Production promotion is blocked by an unresolved ${blocking.severity} ${scanType} finding.`);
  }
  const header=await db.prepare("SELECT last_verified_at FROM security_header_policies WHERE environment='production' AND status='active'").first<any>(),edge=await db.prepare("SELECT verified_at,waf_mode,ddos_managed FROM security_edge_controls WHERE environment='production' ORDER BY verified_at DESC LIMIT 1").first<any>(),cutoff=Date.now()-30*86400000;
  if(!header?.last_verified_at||Date.parse(String(header.last_verified_at))<cutoff)throw new ApiError(409,"Production security headers must be externally verified within the last 30 days before promotion.");
  if(!edge?.verified_at||Date.parse(String(edge.verified_at))<cutoff||String(edge.waf_mode)!=="block"||!Number(edge.ddos_managed))throw new ApiError(409,"Production WAF/DDoS controls must be verified within the last 30 days before promotion.");
}

export async function saveDeployment(db:OpsDB,userId:string,raw:unknown){
  const x=z.object({id:z.string().optional(),environment:z.enum(["staging","production"]),releaseVersion:z.string().min(1).max(160),previousVersion:z.string().max(160).nullable().optional(),strategy:z.enum(["blue_green","canary","rolling","emergency"]),canaryPercent:z.number().int().min(0).max(100).nullable().optional(),status:z.enum(["planned","deploying","verifying","promoted","rolled_back","failed"]),schemaMigrations:z.array(z.string()).max(200).default([]),healthCriteria:z.record(z.any()).default({}),rollbackPlan:z.record(z.any()).default({})}).parse(raw),depId=x.id||id("deploy"),at=now();
  if(x.strategy==="canary"&&x.canaryPercent==null)throw new ApiError(400,"Canary deployments require canaryPercent.");
  const current=await db.prepare("SELECT environment,release_version,strategy,status FROM ops_deployments WHERE id=?").bind(depId).first<any>();if(current){if(String(current.environment)!==x.environment||String(current.release_version)!==x.releaseVersion||String(current.strategy)!==x.strategy)throw new ApiError(409,"Deployment identity, environment and strategy are immutable after creation.");const transitions:Record<string,string[]>={planned:["planned","deploying","failed"],deploying:["deploying","verifying","failed","rolled_back"],verifying:["verifying","promoted","failed","rolled_back"],promoted:["promoted","rolled_back"],failed:["failed","rolled_back"],rolled_back:["rolled_back"]};if(!(transitions[String(current.status)]||[]).includes(x.status))throw new ApiError(409,`Invalid deployment transition ${current.status} -> ${x.status}.`);}
  if(x.status==="rolled_back"&&!x.previousVersion)throw new ApiError(400,"Rollback requires previousVersion.");
  if(x.environment==="production"&&["deploying","verifying","promoted"].includes(x.status)){
    if(!Object.keys(x.rollbackPlan).length)throw new ApiError(400,"Production deployment requires an explicit rollback plan.");
    if(x.status==="promoted"&&!Object.keys(x.healthCriteria).length)throw new ApiError(400,"Production promotion requires explicit health criteria evidence.");
    if(x.status==="promoted")await assertProductionSecurityReleaseGate(db,x.releaseVersion,x.strategy,x.healthCriteria);
    for(const migration of x.schemaMigrations){const ctl=await db.prepare("SELECT backward_compatible,rollback_strategy FROM ops_migration_controls WHERE migration_name=?").bind(migration).first<any>();if(!ctl)throw new ApiError(409,`Migration ${migration} has no registered deployment control.`);if(x.strategy!=="emergency"&&!Number(ctl.backward_compatible))throw new ApiError(409,`Migration ${migration} is not marked backward-compatible for ${x.strategy}.`);if(!String(ctl.rollback_strategy||"").trim())throw new ApiError(409,`Migration ${migration} has no rollback strategy.`);}
  }
  await db.batch([db.prepare(`INSERT INTO ops_deployments(id,environment,release_version,previous_version,strategy,canary_percent,status,schema_migrations_json,health_criteria_json,rollback_plan_json,started_at,promoted_at,rolled_back_at,completed_at,created_by_user_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET status=excluded.status,canary_percent=excluded.canary_percent,health_criteria_json=excluded.health_criteria_json,rollback_plan_json=excluded.rollback_plan_json,promoted_at=excluded.promoted_at,rolled_back_at=excluded.rolled_back_at,completed_at=excluded.completed_at`).bind(depId,x.environment,x.releaseVersion,x.previousVersion||null,x.strategy,x.canaryPercent??null,x.status,JSON.stringify(x.schemaMigrations),JSON.stringify(x.healthCriteria),JSON.stringify(x.rollbackPlan),["deploying","verifying","promoted","failed","rolled_back"].includes(x.status)?at:null,x.status==="promoted"?at:null,x.status==="rolled_back"?at:null,["promoted","rolled_back","failed"].includes(x.status)?at:null,userId,at),db.prepare("INSERT INTO ops_deployment_events(id,deployment_id,event_type,actor_user_id,payload_json,created_at) VALUES(?,?,?,?,?,?)").bind(id("depevt"),depId,`deployment.${x.status}`,userId,JSON.stringify({strategy:x.strategy,canaryPercent:x.canaryPercent??null,releaseVersion:x.releaseVersion,schemaMigrations:x.schemaMigrations}),at)]);return{id:depId,status:x.status};
}

export async function runTrackedWorker<T>(db:OpsDB,workerKey:string,servicePrincipalId:string,work:()=>Promise<T>):Promise<T>{const runId=id("workrun"),started=now();await db.prepare("INSERT INTO ops_worker_runs(id,worker_key,service_principal_id,status,started_at,details_json) VALUES(?,?,?,'running',?,'{}')").bind(runId,workerKey,servicePrincipalId,started).run();try{const result:any=await work(),processed=Number(result?.processed??result?.results?.length??result?.checks?.length??0),failed=Number(result?.failed??result?.dead??0);await db.prepare("UPDATE ops_worker_runs SET status=?,finished_at=?,processed_count=?,failed_count=?,details_json=? WHERE id=?").bind(failed?"partial":"succeeded",now(),processed,failed,JSON.stringify({summary:result}),runId).run();return result;}catch(e){await db.prepare("UPDATE ops_worker_runs SET status='failed',finished_at=?,failed_count=1,error=? WHERE id=?").bind(now(),e instanceof Error?e.message:String(e),runId).run();throw e;}}

export async function deliverOperationalAlerts(db:OpsDB,webhookUrl:string,webhookToken="",limit=50){
  if(!webhookUrl)return{configured:false,processed:0,sent:0,retried:0,dead:0};
  const target=safeOutboundHttpsUrl(webhookUrl,"Operational alert webhook");
  const rows=(await db.prepare("SELECT d.*,i.dedupe_key,i.severity,i.status incident_status,i.title,i.summary,i.opened_at,i.resolved_at,i.metadata_json FROM ops_alert_deliveries d JOIN ops_incidents i ON i.id=d.incident_id WHERE d.status IN ('pending','retry') AND d.available_at<=? ORDER BY CASE i.severity WHEN 'critical' THEN 0 ELSE 1 END,d.created_at LIMIT ?").bind(now(),Math.min(200,Math.max(1,limit))).all<any>()).results;let sent=0,retried=0,dead=0;
  for(const row of rows){const leased=await db.prepare("UPDATE ops_alert_deliveries SET status='leased',leased_at=?,attempts=attempts+1,updated_at=? WHERE id=? AND status IN ('pending','retry') RETURNING attempts,max_attempts").bind(now(),now(),row.id).first<any>();if(!leased)continue;const payload=JSON.stringify({source:"fore",eventType:row.event_type,target:row.notification_target,incident:{id:row.incident_id,dedupeKey:row.dedupe_key,severity:row.severity,status:row.incident_status,title:row.title,summary:row.summary,openedAt:row.opened_at,resolvedAt:row.resolved_at,metadata:JSON.parse(String(row.metadata_json||"{}"))}}),digest=await sha256(payload);try{const r=await fetch(target.toString(),{method:"POST",redirect:"error",headers:{"content-type":"application/json","user-agent":"Cove-Operations/1.0",...(webhookToken?{"authorization":`Bearer ${webhookToken}`}:{})},body:payload});if(!r.ok)throw new Error(`Alert endpoint returned ${r.status}.`);await db.prepare("UPDATE ops_alert_deliveries SET status='sent',sent_at=?,response_status=?,last_error='',payload_sha256=?,updated_at=? WHERE id=?").bind(now(),r.status,digest,now(),row.id).run();sent++;}catch(e){const message=e instanceof Error?e.message:String(e),attempts=Number(leased.attempts||1),max=Number(leased.max_attempts||8);if(attempts>=max){await db.prepare("UPDATE ops_alert_deliveries SET status='dead',last_error=?,payload_sha256=?,updated_at=? WHERE id=?").bind(message,digest,now(),row.id).run();dead++;}else{const delay=Math.min(3600,30*Math.pow(2,Math.max(0,attempts-1))),available=new Date(Date.now()+delay*1000).toISOString();await db.prepare("UPDATE ops_alert_deliveries SET status='retry',available_at=?,last_error=?,payload_sha256=?,updated_at=? WHERE id=?").bind(available,message,digest,now(),row.id).run();retried++;}}}
  return{configured:true,processed:rows.length,sent,retried,dead};
}

export async function recordCapacityTest(db:OpsDB,userId:string,raw:unknown){const x=z.object({environment:z.enum(["staging","production-shadow"]),scenarioKey:z.string().min(1).max(120),version:z.string().min(1).max(120),targetRps:z.number().int().positive(),durationSeconds:z.number().int().positive(),achievedRps:z.number().nonnegative(),p50Ms:z.number().int().nonnegative().nullable().optional(),p95Ms:z.number().int().nonnegative().nullable().optional(),p99Ms:z.number().int().nonnegative().nullable().optional(),errorRateBps:z.number().int().min(0).max(10000).nullable().optional(),saturation:z.record(z.any()).default({}),status:z.enum(["planned","running","passed","failed"]),artifactUrl:z.string().max(1000).default("")}).parse(raw),testId=id("cap"),at=now();await db.prepare("INSERT INTO ops_capacity_tests(id,environment,scenario_key,version,target_rps,duration_seconds,achieved_rps,p50_ms,p95_ms,p99_ms,error_rate_bps,saturation_json,status,artifact_url,run_by_user_id,started_at,finished_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(testId,x.environment,x.scenarioKey,x.version,x.targetRps,x.durationSeconds,x.achievedRps,x.p50Ms??null,x.p95Ms??null,x.p99Ms??null,x.errorRateBps??null,JSON.stringify(x.saturation),x.status,x.artifactUrl,userId,x.status!=="planned"?at:null,["passed","failed"].includes(x.status)?at:null,at).run();return{id:testId};}

export async function enqueueOpsJob(db:OpsDB,raw:unknown){const x=z.object({queueKey:z.string().min(1),jobType:z.string().min(1).max(120),dedupeKey:z.string().max(240).nullable().optional(),payload:z.record(z.any()).default({}),priority:z.number().int().min(0).max(1000).default(100),availableAt:z.string().datetime().optional()}).parse(raw),q=await db.prepare("SELECT max_attempts FROM ops_queue_definitions WHERE queue_key=?").bind(x.queueKey).first<any>();if(!q)throw new ApiError(400,"Unknown operations queue.");const jobId=id("job"),at=now();try{await db.prepare("INSERT INTO ops_jobs(id,queue_key,job_type,dedupe_key,payload_json,status,priority,attempts,max_attempts,available_at,created_at,updated_at) VALUES(?,?,?,?,?,'pending',?,0,?,?,?,?)").bind(jobId,x.queueKey,x.jobType,x.dedupeKey||null,JSON.stringify(x.payload),x.priority,Number(q.max_attempts),x.availableAt||at,at,at).run();}catch{if(x.dedupeKey){const existing=await db.prepare("SELECT id,status FROM ops_jobs WHERE queue_key=? AND dedupe_key=? AND status IN ('pending','leased','retry')").bind(x.queueKey,x.dedupeKey).first<any>();if(existing)return{...existing,deduplicated:true};}throw new ApiError(409,"The job could not be queued.");}return{id:jobId,status:"pending"};}

export async function leaseOpsJobs(db:OpsDB,workerId:string,queueKey:string,limit=10){const q=await db.prepare("SELECT lease_seconds FROM ops_queue_definitions WHERE queue_key=?").bind(queueKey).first<any>();if(!q)throw new ApiError(400,"Unknown operations queue.");const at=now(),leaseUntil=new Date(Date.now()+Number(q.lease_seconds)*1000).toISOString();await db.prepare("UPDATE ops_jobs SET status='retry',leased_by=NULL,lease_until=NULL,available_at=?,last_error=CASE WHEN last_error='' THEN 'lease expired' ELSE last_error END,updated_at=? WHERE queue_key=? AND status='leased' AND lease_until IS NOT NULL AND lease_until<=?").bind(at,at,queueKey,at).run();const rows=(await db.prepare("SELECT id FROM ops_jobs WHERE queue_key=? AND status IN ('pending','retry') AND available_at<=? ORDER BY priority,created_at LIMIT ?").bind(queueKey,at,Math.min(100,Math.max(1,limit))).all<any>()).results,out:any[]=[];for(const row of rows){const leased=await db.prepare("UPDATE ops_jobs SET status='leased',leased_by=?,lease_until=?,attempts=attempts+1,updated_at=? WHERE id=? AND status IN ('pending','retry') AND available_at<=? RETURNING *").bind(workerId,leaseUntil,at,row.id,at).first<any>();if(leased)out.push({...leased,payload:JSON.parse(String(leased.payload_json||"{}"))});}return{jobs:out,leaseUntil};}

export async function finishOpsJob(db:OpsDB,raw:unknown){const x=z.object({jobId:z.string().min(1),workerId:z.string().min(1),success:z.boolean(),error:z.string().max(4000).default(""),retryAfterSeconds:z.number().int().min(1).max(86400).default(60)}).parse(raw),at=now(),job=await db.prepare("SELECT * FROM ops_jobs WHERE id=? AND status='leased' AND leased_by=? AND lease_until>?").bind(x.jobId,x.workerId,at).first<any>();if(!job)throw new ApiError(409,"The job lease is not active for this worker.");if(x.success){await db.prepare("UPDATE ops_jobs SET status='completed',completed_at=?,leased_by=NULL,lease_until=NULL,updated_at=? WHERE id=? AND status='leased' AND leased_by=? AND lease_until>?").bind(at,at,x.jobId,x.workerId,at).run();return{status:"completed"};}const safeError=redactDiagnostic(x.error).slice(0,4000);if(Number(job.attempts)>=Number(job.max_attempts)){const dlq=id("dlq");await db.batch([db.prepare("UPDATE ops_jobs SET status='dead_letter',last_error=?,leased_by=NULL,lease_until=NULL,updated_at=? WHERE id=?").bind(safeError,at,x.jobId),db.prepare("INSERT INTO ops_dead_letters(id,job_id,queue_key,job_type,payload_json,attempts,last_error,first_failed_at,dead_lettered_at) VALUES(?,?,?,?,?,?,?,?,?)").bind(dlq,x.jobId,job.queue_key,job.job_type,job.payload_json,job.attempts,safeError,job.created_at,at)]);return{status:"dead_letter",deadLetterId:dlq};}const available=new Date(Date.now()+x.retryAfterSeconds*1000).toISOString();await db.prepare("UPDATE ops_jobs SET status='retry',last_error=?,leased_by=NULL,lease_until=NULL,available_at=?,updated_at=? WHERE id=?").bind(safeError,available,at,x.jobId).run();return{status:"retry",availableAt:available};}

export async function replayDeadLetter(db:OpsDB,userId:string,raw:unknown){const x=z.object({deadLetterId:z.string().min(1)}).parse(raw),dlq=await db.prepare("SELECT * FROM ops_dead_letters WHERE id=? AND replayed_at IS NULL").bind(x.deadLetterId).first<any>();if(!dlq)throw new ApiError(404,"Unreplayed dead letter not found.");const job=await enqueueOpsJob(db,{queueKey:dlq.queue_key,jobType:dlq.job_type,payload:JSON.parse(String(dlq.payload_json||"{}")),priority:10});await db.prepare("UPDATE ops_dead_letters SET replayed_job_id=?,replayed_by_user_id=?,replayed_at=? WHERE id=?").bind(job.id,userId,now(),x.deadLetterId).run();return{replayed:true,jobId:job.id};}
